'use strict';
// Selection metadata references canonical records. No Japanese content is defined here.
const FAMILY_DEFS=[
 ['identity','Identity, affiliation & basic statements','身分、所屬與基本陳述',['p1','p2','p5','p6']],
 ['questions','Questions & answers','問與答',['p3','p4','p7','p10','p11','p12']],
 ['introductions','Introductions','自我介紹',['p8']],
 ['ownership','Objects, descriptions & ownership','物件、描述與所屬',['p9','p13','p14','p15','p16']],
 ['ranges','Time ranges & schedules','時間範圍與時間表',['p17','p18']]
];
const FAMILY_BY_PATTERN=new Map(FAMILY_DEFS.flatMap(([id,,,patterns])=>patterns.map(p=>[p,id])));
const GRAMMAR_TASKS=[['questions','Question words','疑問詞','Infer the missing question expression from the reply.','從回答推斷缺少的疑問表達。'],['order','Sentence reordering','句子重組','Arrange every token once, including punctuation.','每個詞塊用一次，包括標點。'],['particles','Particles & timetables','助詞與時間表','Fill particle blanks or complete a sentence from a schedule.','填入助詞，或按時間表完成句子。'],['completion','Verbs & phrase completion','動詞與短語完成','Use the context and time cue to complete the supplied sentence.','依上下文與時間提示完成句子。']];
const PICTURE_GROUPS=[['pictures','Picture conversations','圖片對話','Use object positions and each speaker’s perspective.','根據物件位置與說話者視角判斷。'],['situations','Situational expressions','情境表達','Choose an appropriate response for an everyday situation.','選擇適合日常情境的回應。']];
const SCENE_GROUPS={
 standalone:['this-that-2-01','this-that-2-02','this-that-2-03'],modifiers:['this-that-2-04','this-that-2-05','this-that-2-06'],location:['ch3-location-01','ch3-location-02','ch3-location-03'],
 meeting:['meet','intro','likewise','name','neighbour'],attention:['excuse','attention','ch3-excuse'],offering:['offer','ch3-welcome'],thanks:['thanks','thanks-full','ch3-thanks'],reactions:['understand','incorrect','surprise','realise'],
 people:['wh-words-1-17a','wh-words-1-19a'],objects:['wh-words-2-36','wh-what-kind','wh-whose'],places:['ch3-where','ch3-country','ch3-company','ch3-university','ch3-origin'],time:['ch4-time-question','ch4-weekday-question'],numbers:['ch3-floor-question','ch3-price-question','ch4-phone-question']
};
const SCENE_META=new Map();
for(const [topic,ids] of Object.entries(SCENE_GROUPS))for(const id of ids)SCENE_META.set(id,{home:['standalone','modifiers','location'].includes(topic)?'pictures':['people','objects','places','time','numbers'].includes(topic)?'grammar':'situations',topic});
if(DIALOGUE_ENTRIES.some(q=>!SCENE_META.has(q.id)))throw Error('Unclassified active scene');
const SCENE_TOPICS={standalone:['Standalone object words','獨立物件指示詞'],modifiers:['Words before nouns','名詞前的指示詞'],location:['Location expressions','位置表達'],multiple:['Conversations with multiple blanks','多空格對話'],meeting:['Meeting people & introductions','認識他人與自我介紹'],attention:['Getting attention & making requests','引起注意與請求'],offering:['Offering & customer service','提供物品與顧客服務'],thanks:['Thanks & responses','感謝與回應'],reactions:['Replies & reactions','回答與反應'],people:['People & age','人物與年齡'],objects:['Objects & ownership','物件與所屬'],places:['Places & affiliation','場所與所屬'],time:['Time & weekdays','時間與星期'],numbers:['Numbers & prices','數字與價格']};
const nL=(en,zh)=>state.language==='zh-Hant'?zh:en;
function learningScope(key){
 state.learningScopes||={};
 if(!state.learningScopes[key])state.learningScopes[key]={chapter:'all',group:'all',topic:'all',page:0,search:''};
 const s=state.learningScopes[key];s.chapter=String(s.chapter||'all');if(['source-vocabulary','source-expressions'].includes(s.group))s.notice=true;s.group=migrateCategory(s.group||'all');s.topic||='all';return s;
}
function matchesChapter(item,ch){return ch==='all'||(item.chapters||[item.ch]).includes(Number(ch));}
function scopedWords(key='vocabulary',ready=false){const s=learningScope(key);return WORDS.filter(w=>(!ready||wordGameReady(w))&&matchesChapter(w,s.chapter)&&(s.group==='all'||WORD_CLASSIFICATION.get(w.id).group===s.group)&&(s.topic==='all'||WORD_CLASSIFICATION.get(w.id).subgroup===s.topic)&&(!s.search||[w.en,w.zh,w.jp,w.c,w.kana].some(t=>t.toLowerCase().includes(s.search.toLowerCase()))));}
function sceneList(home,scope){return DIALOGUE_ENTRIES.filter(q=>SCENE_META.get(q.id).home===home&&matchesChapter(q,scope.chapter)&&(scope.topic==='all'||SCENE_META.get(q.id).topic===scope.topic));}
function exerciseChapters(q){return [...new Set(q.sourceRefs.flatMap(ref=>{const record=(ref.dataset==='sentences'?SENTENCES:ref.dataset==='dialogues'?dialogueSources:ref.dataset==='numbers'?NUMBER_QUESTIONS:WORDS).find(r=>r.id===ref.id);return record?.chapters||[record?.ch];}).filter(Boolean))];}
function exerciseFamily(q){const ref=q.sourceRefs.find(r=>r.dataset==='sentences');return ref?FAMILY_BY_PATTERN.get(sentenceBy(ref.id)?.pattern):null;}
function grammarExercises(scope=learningScope('grammar')){
 const items=EXAM_BANK.filter(q=>scope.group==='order'?q.kind==='order':scope.group==='particles'?q.schedule||q.skill==='particles':scope.group==='all'?(q.kind==='order'||q.schedule||q.skill==='particles'||q.id.startsWith('verb-')||q.id.startsWith('completion-')):scope.group==='completion'?!q.schedule&&(q.id.startsWith('verb-')||q.id.startsWith('completion-')):false);
 return items.filter(q=>matchesChapter({chapters:exerciseChapters(q)},scope.chapter)&&(scope.topic==='all'||scope.topic==='timetables'?scope.topic!=='timetables'||!!q.schedule:exerciseFamily(q)===scope.topic));
}
function grammarScenes(scope=learningScope('grammar')){return sceneList('grammar',scope);}
function pictureExercises(scope=learningScope('pictures')){return EXAM_BANK.filter(q=>(q.picture||q.pictures)&&matchesChapter({chapters:exerciseChapters(q)},scope.chapter));}
function pictureScenes(scope=learningScope('pictures')){return DIALOGUE_ENTRIES.filter(q=>['pictures','situations'].includes(SCENE_META.get(q.id).home)&&(scope.group==='all'||SCENE_META.get(q.id).home===scope.group)&&matchesChapter(q,scope.chapter)&&(scope.topic==='all'||SCENE_META.get(q.id).topic===scope.topic));}
function scopeOptions(key){const s=learningScope(key),all=[['all',nL('All groups','全部組別')]];let groups,topics=[];
 if(['vocabulary','reference','handwriting'].includes(key)){
  groups=LEARNING_TAXONOMY.filter(g=>WORDS.some(w=>g.ids.includes(w.id)&&matchesChapter(w,s.chapter)&&(key==='reference'||wordGameReady(w))&&(key!=='handwriting'||hasKanji(w)))).map(g=>[g.id,nL(g.label,g.zh)]);
  topics=(LEARNING_TAXONOMY.find(g=>g.id===s.group)?.subgroups||[]).filter(t=>WORDS.some(w=>t.ids.includes(w.id)&&matchesChapter(w,s.chapter)&&(key==='reference'||wordGameReady(w))&&(key!=='handwriting'||hasKanji(w)))).map(t=>[t.id,nL(t.label,t.zh)]);
 }else if(key==='grammar'){
  groups=GRAMMAR_TASKS.filter(([id])=>id==='questions'?grammarScenes({...s,group:id,topic:'all'}).length:grammarExercises({...s,group:id,topic:'all'}).length).map(([id,en,zh])=>[id,nL(en,zh)]);
  if(s.group==='questions')topics=Object.keys(SCENE_TOPICS).filter(id=>grammarScenes({...s,topic:id}).length).map(id=>[id,nL(...SCENE_TOPICS[id])]);
  else if(s.group!=='all'){topics=FAMILY_DEFS.filter(([id])=>grammarExercises({...s,topic:id}).length).map(([id,en,zh])=>[id,nL(en,zh)]);if(s.group==='particles'&&grammarExercises({...s,topic:'timetables'}).length)topics.push(['timetables',nL('Timetable entries','時間表項目')]);}
 }else{
  groups=PICTURE_GROUPS.filter(([id])=>pictureScenes({...s,group:id,topic:'all'}).length).map(([id,en,zh])=>[id,nL(en,zh)]);
  topics=Object.keys(SCENE_TOPICS).filter(id=>pictureScenes({...s,topic:id}).length).map(id=>[id,nL(...SCENE_TOPICS[id])]);
  if(s.group!=='situations'&&pictureExercises(s).length)topics.push(['multiple',nL(...SCENE_TOPICS.multiple)]);
 }
 return {groups:all.concat(groups),topics:[['all',nL('All topics','全部主題')],...topics]};
}
function normalizeLearningScope(key){const s=learningScope(key);let o=scopeOptions(key);if(!o.groups.some(([id])=>id===s.group)){s.group='all';s.topic='all';s.notice=true;o=scopeOptions(key);}if(!o.topics.some(([id])=>id===s.topic))s.topic='all';return s;}
function selectionControls(key){const s=learningScope(key);let options=scopeOptions(key);if(!options.groups.some(([id])=>id===s.group)){s.group='all';s.topic='all';options=scopeOptions(key);}if(!options.topics.some(([id])=>id===s.topic))s.topic='all';return `<div class="learning-filters" data-scope="${key}">${selectControl(key,'chapter',nL('Chapter','課次'),[['all',nL('All chapters','全部課次')],...CHAPTERS.map(ch=>[String(ch),translateText(chapterLabel(ch))])],s.chapter)}${selectControl(key,'group',key==='grammar'?nL('Task','作答任務'):nL('Content group','內容組別'),options.groups,s.group)}${selectControl(key,'topic',nL('Subgroup / topic','小組／主題'),options.topics,s.topic)}</div>`;}
function selectControl(key,field,label,options,value){return `<label class="field-label">${esc(label)}<select class="input" data-learning-scope="${key}" data-learning-field="${field}">${options.map(([id,en])=>`<option value="${esc(id)}" ${id===value?'selected':''}>${esc(en)}</option>`).join('')}</select></label>`;}
function selectionSummary(key,count,unit=nL('playable words','可練習詞條')){const s=learningScope(key),o=scopeOptions(key);return `<p class="selection-summary" role="status">${esc(s.chapter==='all'?nL('All chapters','全部課次'):translateText(chapterLabel(s.chapter)))} · ${esc(o.groups.find(([id])=>id===s.group)?.[1]||nL('All groups','全部組別'))} · ${esc(o.topics.find(([id])=>id===s.topic)?.[1]||nL('All topics','全部主題'))} · <strong>${count} ${unit}</strong></p>`;}
function lessonButton(label,data,disabled=false){return `<button class="button primary" ${data} ${disabled?'disabled':''}>${label}</button>`;}
function learningTitle(en,zh,desc,cn){const section=({Vocabulary:"vocabulary", "Word reference":"reference", "Kanji Writing":"handwriting", "Grammar & Sentences":"grammar", "Pictures & Dialogue":"pictures", "Mixed practice":"mixed"})[en];return `<div class="lulu-intro">${section?luluSectionArt(section):''}<div><h1>${nL(en,zh)}</h1><p>${nL(desc,cn)}</p></div></div>`;}
function safeLearningNote(text){return /PDF|\bp\.?\s*\d|pages?|printed|CSV|source|paper|syllabus|課本.*頁|試卷|試題|匯入/iu.test(text||'')?'':text||'';}
function lexicalCard(w){const ready=wordGameReady(w),related=DIALOGUE_ENTRIES.filter(q=>dialogueForms(q).some(f=>f.word===w.id));return `<article class="paper guide-card" data-lexical-id="${w.id}">${vocabularyVisual(w,true)}<h2 class="jp" lang="ja">${esc(hasKanji(w)?w.c:w.jp)}</h2><p class="jp" lang="ja">${esc(w.kana)}</p><p>${esc(nL(w.en,w.zh))}</p><p class="small">${esc(sourceTag(w))}${WORD_CLASSIFICATION.get(w.id).tags.includes('counter')?' · '+nL('Counter','量詞'):''}</p>${ready?`<span class="status-badge">${esc(translateText(status(w.id)))}</span>`:''}${!ready?`<p>${nL('Available in the reference. Reading needs checking before practice.','可在詞語參考查閱；讀音確認後才能練習。')}</p>`:''}${learningWordNote(w)?`<p>${esc(learningWordNote(w))}</p>`:''}${related.map(q=>`<button class="scope-link" data-related-scene="${q.id}">${nL('Related practice','相關練習')}: ${esc(nL(q.scene,q.sceneZh||translateText(q.scene)))}</button>`).join('')}</article>`;}
function listPage(items,scope,renderItem,size=18){if(!items.length)return `<div class="lulu-empty" role="status">${luluSectionArt('empty')}<p>${nL('No items match this selection. Choose another group or clear the search.','沒有符合此範圍的項目，請選其他組別或清除搜尋。')}</p></div>`;const last=Math.max(0,Math.ceil(items.length/size)-1),s=learningScope(scope);s.page=Math.max(0,Math.min(last,s.page||0));return `<p class="small">${nL('Showing','顯示')} ${items.length?s.page*size+1:0}–${Math.min((s.page+1)*size,items.length)} / ${items.length}</p><div class="learning-list">${items.slice(s.page*size,(s.page+1)*size).map(renderItem).join('')}</div><div class="card-actions"><button class="button ghost" data-learning-page="${scope}" data-page="${s.page-1}" ${s.page?'':'disabled'}>${nL('Previous page','上一頁')}</button><span>${s.page+1}/${last+1}</span><button class="button ghost" data-learning-page="${scope}" data-page="${s.page+1}" ${s.page<last?'':'disabled'}>${nL('Next page','下一頁')}</button></div>`;}
function learningVocabulary(key='vocabulary'){
 const s=normalizeLearningScope(key),reference=key==='reference',handwriting=key==='handwriting',records=scopedWords(key,!reference).filter(w=>!handwriting||hasKanji(w)),playable=records.filter(wordGameReady);
 return `<section class="study-wrap">${learningTitle(reference?'Word reference':handwriting?'Kanji Writing':'Vocabulary',reference?'詞語參考':handwriting?'漢字書寫':'詞彙',reference?'Browse the complete word inventory, including entries not yet available for practice.':'Learn words, meanings, readings and written forms.',reference?'查閱全部詞條，包括尚未開放練習的項目。':'學習詞彙、意思、讀音與書寫形式。')}${selectionControls(key)}<label class="field-label">${nL('Search words','搜尋詞語')}<input class="input" type="search" data-learning-search="${key}" value="${esc(s.search)}"></label>${s.notice?`<p role="status">${nL('Word groups have been reorganised. All groups is selected; choose a group to focus your practice.','詞語組別已重新整理。目前選擇全部組別，請選組別以專注練習。')}</p>`:''}${selectionSummary(key,playable.length)}${s.group!=='all'?`<h2>${nL(LEARNING_TAXONOMY.find(g=>g.id===s.group).label,LEARNING_TAXONOMY.find(g=>g.id===s.group).zh)}</h2><p>${nL(LEARNING_TAXONOMY.find(g=>g.id===s.group).description,LEARNING_TAXONOMY.find(g=>g.id===s.group).descriptionZh)}</p>`:''}${!reference&&!handwriting&&s.group==='all'?`<h2>${nL('All vocabulary','全部詞彙')}</h2>`:''}${reference?`<p>${records.length} ${nL('reference entries','參考詞條')}</p>`:''}<div class="card-actions">${handwriting?lessonButton(nL('Draw & self-check','手寫與自評'),'data-learning-start="handwriting"',!playable.length):lessonButton(nL('Recall','回想'),`data-learning-start="recall" data-scope="${key}"`,!playable.length)+lessonButton(nL('Rebuild','重組'),`data-learning-start="rebuild" data-scope="${key}"`,!playable.length)}${!handwriting&&playable.some(hasKanji)?lessonButton(nL('Kanji recall','漢字回想')+' · '+playable.filter(hasKanji).length,`data-learning-start="kanji-recall" data-scope="${key}"`):''}${!handwriting?`<button class="button ghost" data-view="handwriting-menu">${nL('Kanji Writing','漢字書寫')}</button><button class="button ghost" data-view="number-menu">${nL('Numbers','數字')}</button>`:''}</div>${listPage(records,key,lexicalCard)}</section>`;
}
function sceneCount(items){return `${items.length} ${nL('scenes','情境')} · ${items.reduce((n,q)=>n+dialogueForms(q).length,0)} ${nL('forms','形式')}`;}
function sceneGuide(q){return `<div data-learning-scene="${q.id}">${conversationCard(q)}</div>`;}
function grammarPatternCards(scope=learningScope('grammar')){const ids=new Set(grammarExercises(scope).flatMap(q=>q.sourceRefs.filter(r=>r.dataset==='sentences').map(r=>sentenceBy(r.id).pattern)));return FAMILY_DEFS.map(([id,en,zh,patterns])=>{const list=PATTERNS.filter(p=>patterns.includes(p.id)&&ids.has(p.id));return list.length?`<section><h2>${nL(en,zh)}</h2>${list.map(p=>`<article class="paper" data-pattern-example="${p.id}" tabindex="-1">${luluSectionArt('grammar','lulu-small')}<h3>${esc(translateText(p.title))}</h3><p class="jp" lang="ja">${esc(p.formula)}</p><p>${esc(translateText(p.tip))}</p><p class="jp" lang="ja">${esc(SENTENCES.find(s=>s.pattern===p.id&&matchesChapter(s,scope.chapter))?.tokens.join('')||'')}</p><p>${SENTENCES.filter(s=>s.pattern===p.id&&matchesChapter(s,scope.chapter)).length} ${nL('sentences','句子')}</p><button class="scope-link" data-learning-pattern="${p.id}">${nL('Practise this pattern','練習此句型')}</button></article>`).join('')}</section>`:'';}).join('');}
function grammarMenu(){const s=normalizeLearningScope('grammar'),questions=s.group==='questions',scenes=questions?grammarScenes(s):[],exercises=grammarExercises(s),count=s.group==='all'?exercises.length+grammarScenes(s).length:questions?scenes.length:exercises.length;
 return `<section class="study-wrap">${learningTitle('Grammar & Sentences','文法與句子','Learn sentence patterns and practise completing or constructing sentences.','學習句型，練習完成或組成句子。')}${selectionControls('grammar')}${selectionSummary('grammar',count,s.group==='all'?nL('learning items','學習項目'):questions?nL('scenes','情境'):nL('questions','題'))}${s.group==='all'?`<div class="learning-list">${GRAMMAR_TASKS.map(([id,en,zh,desc,cn])=>{const sub={...s,group:id,topic:'all'},n=id==='questions'?grammarScenes(sub).length:grammarExercises(sub).length;return `<article class="paper">${luluTaskArt(id)}<h2>${nL(en,zh)}</h2><p>${nL(desc,cn)}</p><p>${n} ${id==='questions'?nL('scenes','情境'):nL('questions','題')}</p>${lessonButton(nL('Choose this task','選擇此任務'),`data-learning-group="${id}" data-scope="grammar"`,!n)}</article>`;}).join('')}</div>`:`<h2>${nL('Practice method','練習方式')}</h2><p>${nL('Choose how much help you want. Only available methods are shown.','選擇需要的輔助程度；僅顯示可用方式。')}</p><div class="card-actions">${lessonButton(nL('Example','範例'),'data-learning-start="grammar-example"',!count)}${questions?lessonButton(nL('Guided practice · Matching','引導練習 · 配對'),'data-learning-start="grammar-matching"',!count)+lessonButton(nL('Guided practice · Rebuild','引導練習 · 重組'),'data-learning-start="grammar-rebuild"',!count):lessonButton(nL('Guided practice','引導練習'),'data-learning-start="grammar-guided"',!count)}${lessonButton(nL('Independent practice','獨立練習')+(questions?' · '+independentSceneExercises(scenes).length+' '+nL('questions','題'):''),'data-learning-start="grammar-independent"',!count)+(questions&&independentSceneExercises(scenes,true).length?lessonButton(nL('Independent practice · whole question','獨立練習 · 完整問題'),'data-learning-start="grammar-independent-whole"'):'' )}</div>${questions?`<h2 id="learning-examples" tabindex="-1">${nL('Examples','範例')}</h2><p>${sceneCount(scenes)}</p>${listPage(scenes,'grammar',sceneGuide,4)}`:grammarPatternCards(s)}`}${learningProgressPanel()}<div class="card-actions"><button class="button ghost" data-view="mixed">${nL('Mixed practice','綜合練習')}</button><button class="button ghost" data-view="number-menu">${nL('Number readings','數字讀音')}</button></div></section>`;
}
function picturesMenu(){const s=normalizeLearningScope('pictures'),scenes=pictureScenes(s),multi=s.topic==='multiple'?pictureExercises(s):[],count=multi.length||scenes.length;
 return `<section class="study-wrap">${learningTitle('Pictures & Dialogue','圖片與對話','Interpret pictures and use expressions in conversations and everyday situations.','理解圖片，在對話與日常情境中運用表達。')}${selectionControls('pictures')}${selectionSummary('pictures',count,multi.length?nL('questions','題'):nL('scenes','情境'))}${s.group==='all'?`<div class="card-actions">${lessonButton(nL('Matching','配對'),'data-learning-start="picture-matching"',!count)}${lessonButton(nL('Rebuild','重組'),'data-learning-start="picture-rebuild"',!count)}${lessonButton(nL('Independent practice','獨立練習')+' · '+independentSceneExercises(scenes).length+' '+nL('questions','題'),'data-learning-start="picture-independent"',!independentSceneExercises(scenes).length)}</div><div class="learning-list">${PICTURE_GROUPS.map(([id,en,zh,desc,cn])=>`<article class="paper">${luluTaskArt(id)}<h2>${nL(en,zh)}</h2><p>${nL(desc,cn)}</p><p>${sceneCount(pictureScenes({...s,group:id,topic:'all'}))}</p>${lessonButton(nL('Choose this group','選擇此組別'),`data-learning-group="${id}" data-scope="pictures"`,!pictureScenes({...s,group:id,topic:'all'}).length)}</article>`).join('')}</div><p>${sceneCount(scenes)}</p>${listPage(scenes,'pictures',sceneGuide,4)}`:`<h2>${nL('Practice method','練習方式')}</h2><div class="card-actions">${lessonButton(nL('Example','範例'),'data-learning-start="picture-example"',!count)}${multi.length?lessonButton(nL('Guided practice','引導練習'),'data-learning-start="picture-guided"'):lessonButton(nL('Matching','配對'),'data-learning-start="picture-matching"',!count)+lessonButton(nL('Rebuild','重組'),'data-learning-start="picture-rebuild"',!count)}${lessonButton(nL('Independent practice','獨立練習')+' · '+(multi.length||independentSceneExercises(scenes).length)+' '+nL('questions','題'),'data-learning-start="picture-independent"',!(multi.length||independentSceneExercises(scenes).length))+(independentSceneExercises(scenes,true).length?lessonButton(nL('Independent practice · whole response','獨立練習 · 完整回應'),'data-learning-start="picture-independent-whole"'):'' )}</div>${scenes.length?`<h2 id="learning-examples" tabindex="-1">${nL('Examples','範例')}</h2><p>${sceneCount(scenes)}</p>${listPage(scenes,'pictures',sceneGuide,4)}`:''}`}<button class="scope-link" data-view="grammar">${nL('Related practice: Question words','相關練習：疑問詞')}</button></section>`;
}
function mixedMenu(){return `<section class="study-wrap paper">${learningTitle('Mixed practice','綜合練習','Combine sentence skills, question words, number readings and kanji recall.','綜合句子技能、疑問詞、數字讀音與漢字回想。')}<p>20 ${nL('points','分')} · ${nL('Independent practice','獨立練習')}</p>${lessonButton(nL('Start mixed practice','開始綜合練習'),'data-learning-start="mixed"')}${learningProgressPanel()}<p>${nL('For focused practice, choose a task in Grammar & Sentences or a word group in Vocabulary.','如要專注練習，請在文法與句子選擇任務，或在詞彙選擇組別。')}</p></section>`;}
function launchExistingExercises(items,stage,home){if(!items.length)return;examRound={skill:home==='grammar'?'wordOrder':home==='pictures'?'demonstratives':'exam',stage,items:shuffle(items),index:0,answers:[],checked:false,results:[],earned:0,total:items.reduce((n,q)=>n+q.marks.reduce((a,b)=>a+b,0),0),assisted:stage!=='write',ink:[],chosen:[],learningTitle:home==='grammar'?GRAMMAR_TASKS.find(t=>t[0]===learningScope('grammar').group)?.slice(1,3):home==='number-menu'?["Numbers","數字"]:['bank','vocabulary-content'].includes(home)?["Vocabulary","詞彙"]:["Pictures & Dialogue","圖片與對話"]};state.learningReturn=home;state.view='exam-practice';render();}
function independentSceneExercises(scenes,whole=false){const forms=new Set(scenes.flatMap(dialogueForms).map(q=>q.id));return EXAM_BANK.filter(q=>(q.id.startsWith('recall-')&&q.whole===whole||!whole&&q.picture)&&q.sourceRefs.some(ref=>ref.dataset==='dialogues'&&forms.has(ref.id)));}
function learningStart(method){
 if(method==='kanji-recall'){const key=state.learningLaunchScope||'vocabulary',ids=new Set(scopedWords(key,true).filter(hasKanji).map(w=>w.id));launchExistingExercises(EXAM_BANK.filter(q=>q.skill==='kanji'&&q.sourceRefs.some(r=>r.dataset==='words'&&ids.has(r.id))),'write',key==='reference'?'bank':'vocabulary-content');return;}
 if(['recall','rebuild','handwriting'].includes(method)){const key=state.learningLaunchScope||'vocabulary',mode=method==='recall'?'write':method==='rebuild'?'vocabulary-rebuild':'kanji-writing',words=scopedWords(method==='handwriting'?'handwriting':key,true).filter(w=>method!=='handwriting'||hasKanji(w));state.learningReturn=method==='handwriting'?'handwriting-menu':key==='reference'?'bank':'vocabulary-content';startWordPractice(mode,words.map(w=>w.id),nL('Selected vocabulary','所選詞彙'));return;}
 if(method==='mixed'){state.learningReturn='mixed';exStart('exam');return;}
 const grammar=method.startsWith('grammar'),home=grammar?'grammar':'pictures',s=learningScope(home),scenes=grammar?grammarScenes(s):pictureScenes(s),items=grammar?grammarExercises(s):pictureExercises(s),stage=method.endsWith('example')?'example':method.includes('independent')?'write':'practice';state.learningReturn=home;
 if((grammar&&s.group==='questions'||!grammar&&s.topic!=='multiple')&&!method.includes('independent')){
  if(stage==='example'){state.learningExamples=home;render();document.getElementById('learning-examples')?.focus();return;}
  const ids=scenes.map(q=>q.id);if(!ids.length)return;startActivity(method.endsWith('matching')?'dialogue-choice':'dialogue-tiles',ids,null,{ids,learningHome:home});return;
 }
 if(grammar&&s.group==='order'&&stage==='example'){state.learningExamples='grammar';render();document.querySelector('[data-pattern-example]')?.focus();return;}
 if(grammar&&s.group==='order'&&stage!=='example'){
  const ids=items.map(q=>q.sourceRefs.find(r=>r.dataset==='sentences').id);if(!ids.length)return;state.view='sentences';state.filter.ch=s.chapter;state.pattern='all';begin('sentences',ids);state.round.learningGuided=stage==='practice';state.round.assisted=stage==='practice';if(stage==='practice')state.round.hint=true;render();return;
 }
 launchExistingExercises((grammar&&s.group==='questions'||!grammar&&s.topic!=='multiple')?independentSceneExercises(scenes,method.endsWith('whole')):items,stage,home);
}
function learningChange(key,field,value){const s=learningScope(key);s[field]=value;s.page=0;s.notice=false;if(field==='group')s.topic='all';if(field==='chapter'||field==='group'){const o=scopeOptions(key);if(!o.groups.some(([id])=>id===s.group))s.group='all';if(!scopeOptions(key).topics.some(([id])=>id===s.topic))s.topic='all';}state.learningExamples=null;save();render();}
document.addEventListener('change',e=>{const d=e.target.dataset;if(d.learningScope)learningChange(d.learningScope,d.learningField,e.target.value);});
document.addEventListener('input',e=>{const d=e.target.dataset;if(d.learningSearch){const s=learningScope(d.learningSearch);s.search=e.target.value;s.page=0;save();render();}});
document.addEventListener('click',e=>{const t=e.target.closest('[data-learning-start],[data-learning-group],[data-learning-page],[data-learning-pattern],[data-related-scene]');if(!t||t.disabled)return;const d=t.dataset;if(d.learningStart){state.learningLaunchScope=d.scope;learningStart(d.learningStart);}else if(d.learningGroup)learningChange(d.scope,'group',d.learningGroup);else if(d.learningPage){learningScope(d.learningPage).page=Number(d.page);render();}else if(d.learningPattern){const s=learningScope('grammar');s.group='order';s.topic=FAMILY_BY_PATTERN.get(d.learningPattern);state.filter.ch=s.chapter;state.pattern=d.learningPattern;const ids=SENTENCES.filter(x=>x.pattern===d.learningPattern&&matchesChapter(x,s.chapter)).map(x=>x.id);if(ids.length){state.learningReturn='grammar';state.view='sentences';begin('sentences',ids);render();}}else if(d.relatedScene){const q=DIALOGUE_ENTRIES.find(q=>q.id===d.relatedScene),meta=SCENE_META.get(q.id),home=meta.home==='grammar'?'grammar':'pictures',s=learningScope(home);s.chapter='all';s.group=home==='grammar'?'questions':meta.home;s.topic=meta.topic;s.page=Math.floor((home==='grammar'?grammarScenes(s):pictureScenes(s)).findIndex(x=>x.id===q.id)/4);navigate(home);}});
document.addEventListener('change',e=>{if(!e.target.dataset.numberFilter)return;const key=e.target.dataset.numberFilter==='chapter'?'numberChapter':'numberType';state[key]=e.target.value;state.numberPage=0;if(key==='numberChapter'&&state.numberType!=='all'&&!NUMBER_QUESTIONS.some(q=>numberCategory(q)===state.numberType&&(state.numberChapter==='all'||q.chapters.includes(Number(state.numberChapter)))))state.numberType='all';save();render();});
document.addEventListener('click',e=>{if(!e.target.closest('[data-number-recall]'))return;const ids=new Set(numberSelection().items.map(q=>q.id));launchExistingExercises(EXAM_BANK.filter(q=>q.number&&ids.has(q.number.id)),'write','number-menu');});
